-- Migration 412: S279 thresholds lane L2 (AA-1096) — the quality registry moves onto the platform settings registry
-- (CIS 407): 151 setting definitions seeded from today's effective values, every one evidence-gated and maker-checker.
--
-- Why. Tech lead S279: quality thresholds are admin-editable WITH a required evidence link (an eval / golden-set run
-- id or a $0 replay). Until now the pass line, the caps and bands, the SEO bands, the detector modes and the claim
-- verdicts lived in registry YAML (services/quality/thresholds.yaml, writing_policy.yaml, taxonomy.yaml), env vars of
-- the worker task (T10_* / T10_SA_MODE / T10_ADJ_MODE / T9_BRIEF_GROUNDING_MODE / T7_DEBATE_MODE / T2_JUDGE_GATE /
-- T3_BACKGROUND_FACTS / AUTO_UPGRADE_THRESHOLD) or code literals (the T7 Channel bars, the debate cut, the T9 blog
-- length band); every change needed a PR, the change_control lock and a redeploy (root audit
-- docs/audits/2026-11-13-S279-session/thresholds-audit/, sections 3.1, 5.5, lane L2).
--
-- What. Rows of shared.setting_definition only (seed block below; scripts/settings/gen_compiled_defaults.py reads it
-- into shared/settings/compiled_defaults.json, tests/unit/test_s279_settings_seed_parity.py keeps the two equal):
--   area quality          12  the pass line 7.0 (every former ref of pass_line reads it), the A1 missing-field cap
--                             4.0, the judge tie band 0.5 and mission-absent cap 6.0, the brand-fit re-score band
--                             6.0-8.0, the T2 cross-brand overlap warning 0.35, the T9 blog length target margin
--                             0.17, the T10 reuse similarity 0.92, the review score band 5 and the top colour band 9,
--                             the A1 auto-upgrade score 8.5 (env AUTO_UPGRADE_THRESHOLD, set nowhere).
--   area seo             11  the meta band 140-155, the title band 45-60, the slug cap 60 and the three writers' meta
--                             aims (T9 130-145, S1 v2 130-148, S1 v1 / T2 145-152) of writing_policy.yaml (D5). Listed
--                             but not editable yet: the A1 / T2 writer prompts and the meta fitters read them when a
--                             process starts, so the API refuses a change (services/quality/quality_settings
--                             START_TIME_REASON) until a follow-up renders them at call time.
--   area content           2  the T9 blog length band 4,700-13,000 characters (services/acp_content_writing/
--                             length_contract.py literals).
--   area quality_modes    24  the gate modes that were worker env vars: T10 F12 scope (warn), F9 brand style (warn),
--                             F14 floor (repair), F9 policy (interim), seed-align (off; 10 classes inherit),
--                             adjudicator (off; 4 classes inherit), T9 brief grounding (off), T7 debate (rank) - each
--                             keeps its env var as an emergency override for one release (none is set in Terraform);
--                             T2 judge gate = brand_fit and T3 background facts = on, the worker's Terraform values
--                             (code defaults brand_fit_mission / off), with no env override (set on the worker only,
--                             the page could not show it; lane L6 removes the two env vars from Terraform).
--   area quality_claims   11  the claim verdicts the gates read: the F9 v2 rules for hypothetical framing and uncited
--                             place background (warn, warn) and the nine F9 class actions (trip_promise hold, the
--                             rest warn).
--   area quality_detectors 81 the mode of every taxonomy.yaml detector (50 enforce, 19 shadow, 12 warn as of today).
--   area t7               10  the debate contested threshold 0.5 and cut fraction 0.5, and the Channel bar of each of
--                             the 8 Channels (needs_demand / needs_questions / needs_said / most_per_hub).
-- Every row: evidence_required = true (a proposal names its eval, golden-set or replay run), approval = maker_checker
-- (a second staff member approves, or a recorded self-approval while cis.settings.two_person_approval is off),
-- scope platform, cache 30 s. No setting_value row: every key resolves to its default, today's value, until an
-- administrator approves a change, so applying this file changes no verdict.
--
-- Class: contract (root ADR 0017): rows inserted into an existing table (shared.setting_definition, CIS 407) are
-- config rows; MIG-4 order: this migration-only PR, Infra Migration Apply once every job table is idle, then the code
-- PR (it reads these keys; without them the reader serves the same values from the compiled defaults and the admin
-- page lists the keys only once this file is applied). The definition guard trigger lets only cis_owner write: Migration
-- Apply runs cis/ files as cis_owner.
--
-- Re-run: ON CONFLICT (key) DO NOTHING (an identical row is already there; a later migration changes a definition).
--
-- Number. 411 is the highest on main (CIS 408-411, the tenant erasure saga); this file takes 412 and the t9_write v8
-- registration 413 (batch cis 412-413).
--
-- Rollback (a new forward migration, after the code is reverted): DELETE FROM shared.setting_value / setting_definition
-- WHERE key LIKE 'cis.quality%' OR key LIKE 'cis.seo.%' OR key IN (the t9 / t7 keys) - a destructive file, DRY RUN.
--
-- X1. One BEGIN … COMMIT block, no role switch.

BEGIN;

SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced
  FROM jsonb_to_recordset($seed$[
{"key": "cis.quality.pass_line", "app": "cis", "area": "quality", "label": "Quality pass line", "description": "The quality score every writer and judge gate shares: A1 retry / human review, the Master publish floor, the Review approve button, T2 version status, the T3 revision trigger, the T7 debate brand-fit cut, the legacy validation export and the golden-set verdict (services/quality/thresholds.yaml keys that ref pass_line). Seeded at 7.0. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "score (0-10)", "min_value": 5.0, "max_value": 9.5, "allowed_values": null, "default_value": 7.0, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.a1_missing_field_cap", "app": "cis", "area": "quality", "label": "A1 missing-field score cap", "description": "A MISSING_FIELD finding caps the A1 validate score at this value, below the pass line (AA-216). Must stay under the pass line. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "score (0-10)", "min_value": 0.0, "max_value": 9.5, "allowed_values": null, "default_value": 4.0, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.judge_tie_band", "app": "cis", "area": "quality", "label": "Brand-fit judge tie band", "description": "Half-width of the band around the judge pass line where the Jev a1_brand_fit question breaks a tie (AA-692). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "score", "min_value": 0.0, "max_value": 2.0, "allowed_values": null, "default_value": 0.5, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.judge_mission_absent_cap", "app": "cis", "area": "quality", "label": "T2 brand-fit cap when the mission is absent", "description": "The T2 brand-fit score is capped here when the tenant's mission is judged absent (just below the pass line). Must stay under the pass line. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "score (0-10)", "min_value": 0.0, "max_value": 9.5, "allowed_values": null, "default_value": 6.0, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.brand_fit_repeat_band_low", "app": "cis", "area": "quality", "label": "Brand-fit re-score band: low end", "description": "Low end (inclusive) of the band where an unseeded brand-fit judge score is re-scored twice and the median kept (AA-714). Must not exceed the high end. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "score (0-10)", "min_value": 0.0, "max_value": 10.0, "allowed_values": null, "default_value": 6.0, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.brand_fit_repeat_band_high", "app": "cis", "area": "quality", "label": "Brand-fit re-score band: high end", "description": "High end (inclusive) of the brand-fit re-score band (AA-714). Must not be under the low end. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "score (0-10)", "min_value": 0.0, "max_value": 10.0, "allowed_values": null, "default_value": 8.0, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.t2_cross_brand_overlap_warn", "app": "cis", "area": "quality", "label": "T2 cross-brand overlap warning", "description": "Word 5-gram Jaccard of two brands' versions of one tour at or above which the deterministic cross-brand check warns (AA-1079; AA-741 phase 3 measured a mean of 0.18, max 0.37). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "share", "min_value": 0.05, "max_value": 1.0, "allowed_values": null, "default_value": 0.35, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.t9_blog_length_target_margin", "app": "cis", "area": "quality", "label": "T9 blog length target margin", "description": "How far above the blog length floor every length aim sits (the writer's word floor, the extend repair and the F4 short rewrite): 0.17 = 17 % above the floor (S278: with 0.11, 3 of 9 pieces came in under the floor). The t9_write prompt renders the word floor from it at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "share", "min_value": 0.0, "max_value": 0.5, "allowed_values": null, "default_value": 0.17, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.t10_reuse_similarity", "app": "cis", "area": "quality", "label": "T10 reuse similarity", "description": "Cross-tenant and within-tenant reuse similarity at or above which a match is reported (F10 / within-tenant reuse). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "cosine", "min_value": 0.5, "max_value": 1.0, "allowed_values": null, "default_value": 0.92, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.review_score_band_low", "app": "cis", "area": "quality", "label": "Review score band: critical / low boundary", "description": "Review Queue boundary between a critical and a low score (filter and colour). Must stay under the pass line. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "score (0-10)", "min_value": 0.0, "max_value": 9.5, "allowed_values": null, "default_value": 5.0, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.ui_score_band_top", "app": "cis", "area": "quality", "label": "Score colour: top band", "description": "Scores at or above it show green on the admin pages; from the pass line up to it amber, below the pass line red. Must stay above the pass line. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "score (0-10)", "min_value": 5.0, "max_value": 10.0, "allowed_values": null, "default_value": 9.0, "scope_kind": "platform", "impact": "low", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality.auto_upgrade_threshold", "app": "cis", "area": "quality", "label": "A1 auto-upgrade score", "description": "An opted-in A1 rewrite on the cheap model that scores under this is re-run once on the stronger model (AA-237). Was the env var AUTO_UPGRADE_THRESHOLD (not set anywhere: 8.5). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "numeric", "unit": "score (0-10)", "min_value": 5.0, "max_value": 10.0, "allowed_values": null, "default_value": 8.5, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.meta_min", "app": "cis", "area": "seo", "label": "Meta description: minimum characters", "description": "Shortest meta description the gates, fitters and validators accept. One band for every workflow (writing policy D5): code composes and trims into it. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 60, "max_value": 300, "allowed_values": null, "default_value": 140, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.meta_max", "app": "cis", "area": "seo", "label": "Meta description: maximum characters", "description": "Longest meta description; never under any writer's aim maximum. One band for every workflow (writing policy D5): code composes and trims into it. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 60, "max_value": 320, "allowed_values": null, "default_value": 155, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.title_min", "app": "cis", "area": "seo", "label": "SEO title: minimum characters", "description": "Shortest SEO title the T9 gates and the SEO fit accept. One band for every workflow (writing policy D5): code composes and trims into it. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 10, "max_value": 100, "allowed_values": null, "default_value": 45, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.title_max", "app": "cis", "area": "seo", "label": "SEO title: maximum characters", "description": "Longest SEO title (A1 validate SEO_TITLE_TOO_LONG, T9 gates, the SEO fit). One band for every workflow (writing policy D5): code composes and trims into it. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 20, "max_value": 120, "allowed_values": null, "default_value": 60, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.slug_max", "app": "cis", "area": "seo", "label": "Slug: maximum characters", "description": "Longest URL slug; code cuts at a word boundary. One band for every workflow (writing policy D5): code composes and trims into it. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 20, "max_value": 120, "allowed_values": null, "default_value": 60, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.aim_t9_meta_min", "app": "cis", "area": "seo", "label": "Meta aim, T9 writer + SEO fit: minimum", "description": "Low end of the meta description length the T9 writer + SEO fit prompt asks for. Writers aim below the band (lesson S233: a model overshoots a character target); code then fits the value into the band. It may sit under the band minimum: a deterministic step lands a short value in the band. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 60, "max_value": 320, "allowed_values": null, "default_value": 130, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.aim_t9_meta_max", "app": "cis", "area": "seo", "label": "Meta aim, T9 writer + SEO fit: maximum", "description": "High end of the meta description length the T9 writer + SEO fit prompt asks for; never over the meta band maximum. Writers aim below the band (lesson S233: a model overshoots a character target); code then fits the value into the band. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 60, "max_value": 320, "allowed_values": null, "default_value": 145, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.aim_s1_meta_min", "app": "cis", "area": "seo", "label": "Meta aim, S1 writer v2: minimum", "description": "Low end of the meta description length the S1 writer v2 prompt asks for. Writers aim below the band (lesson S233: a model overshoots a character target); code then fits the value into the band. It may sit under the band minimum: a deterministic step lands a short value in the band. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 60, "max_value": 320, "allowed_values": null, "default_value": 130, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.aim_s1_meta_max", "app": "cis", "area": "seo", "label": "Meta aim, S1 writer v2: maximum", "description": "High end of the meta description length the S1 writer v2 prompt asks for; never over the meta band maximum. Writers aim below the band (lesson S233: a model overshoots a character target); code then fits the value into the band. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 60, "max_value": 320, "allowed_values": null, "default_value": 148, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.aim_t2_meta_min", "app": "cis", "area": "seo", "label": "Meta aim, S1 v1 / T2 rewrite: minimum", "description": "Low end of the meta description length the S1 v1 / T2 rewrite prompt asks for. Writers aim below the band (lesson S233: a model overshoots a character target); code then fits the value into the band. It may not sit under the band minimum (no deterministic short fix on this writer). Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 60, "max_value": 320, "allowed_values": null, "default_value": 145, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.seo.aim_t2_meta_max", "app": "cis", "area": "seo", "label": "Meta aim, S1 v1 / T2 rewrite: maximum", "description": "High end of the meta description length the S1 v1 / T2 rewrite prompt asks for; never over the meta band maximum. Writers aim below the band (lesson S233: a model overshoots a character target); code then fits the value into the band. Not editable yet (the API refuses a change): the A1 / T2 writer prompts and the meta fitters read it when a process starts; a follow-up renders them at call time. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 60, "max_value": 320, "allowed_values": null, "default_value": 152, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.t9.blog_chars_min", "app": "cis", "area": "content", "label": "T9 blog length floor (characters)", "description": "The F4 blog minimum, tag-stripped characters (about 810 words). The writer's word floor sits the target margin above it. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 1000, "max_value": 20000, "allowed_values": null, "default_value": 4700, "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.t9.blog_chars_max", "app": "cis", "area": "content", "label": "T9 blog length ceiling (characters)", "description": "The F4 blog maximum, tag-stripped characters (about 2,240 words). Must be above the floor. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "int", "unit": "characters", "min_value": 2000, "max_value": 40000, "allowed_values": null, "default_value": 13000, "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": null, "cache_s": 30, "enforced": true},
{"key": "cis.quality_modes.t10_f12_scope", "app": "cis", "area": "quality_modes", "label": "T10 F12 scope check mode", "description": "warn: a place outside the piece's scope is reported only. block: a body finding blocks for one sentence repair and holds the piece when it is left (AA-788). The env var stays an emergency override for one release (a badge on this page). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["warn", "block"], "default_value": "warn", "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": "T10_F12_SCOPE_MODE", "cache_s": 30, "enforced": true},
{"key": "cis.quality_modes.t10_f9_brand_style", "app": "cis", "area": "quality_modes", "label": "T10 F9 brand-style check mode", "description": "warn: off-brand wording is reported only. repair: on attempt 1 a flagged body sentence gets one sentence repair (never a hold) (AA-788). The env var stays an emergency override for one release (a badge on this page). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["warn", "repair"], "default_value": "warn", "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": "T10_F9_BRAND_STYLE_MODE", "cache_s": 30, "enforced": true},
{"key": "cis.quality_modes.t10_f14_floor", "app": "cis", "area": "quality_modes", "label": "T10 F14 under-floor rewrite mode", "description": "repair: a social piece under its length floor gets the attempt-1 rewrite (AA-780). warn: the kill switch, reported only. The env var stays an emergency override for one release (a badge on this page). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["repair", "warn"], "default_value": "repair", "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": "T10_F14_FLOOR_MODE", "cache_s": 30, "enforced": true},
{"key": "cis.quality_modes.t10_f9_policy", "app": "cis", "area": "quality_modes", "label": "T10 F9 claim policy mode", "description": "interim: only a trip promise holds, every other F9 class warns (the claim verdicts below). legacy: the pre-W0 verdict (rollback). The env var stays an emergency override for one release (a badge on this page). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["interim", "legacy"], "default_value": "interim", "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": "T10_F9_POLICY_MODE", "cache_s": 30, "enforced": true},
{"key": "cis.quality_modes.t10_seed_align", "app": "cis", "area": "quality_modes", "label": "T10 seed-align checks: mode of every class", "description": "off: the checks do not run. shadow: recorded only. repair: a finding gets one sentence repair, never a hold. hold: like repair, and a promoted fact class may hold (until a class is promoted, hold reads as repair) (AA-789). The env var stays an emergency override for one release (a badge on this page). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["off", "shadow", "repair", "hold"], "default_value": "off", "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": "T10_SA_MODE", "cache_s": 30, "enforced": true},
{"key": "cis.quality_modes.t10_seed_align_optional_as_planned", "app": "cis", "area": "quality_modes", "label": "T10 seed-align: optional as planned", "description": "Mode of the seed-align class optional_as_planned; inherit = the mode of every class above (AA-789). The env var stays an emergency override for one release (a badge on this page). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["inherit", "off", "shadow", "repair", "hold"], "default_value": "inherit", "scope_kind": "platform", "impact": "medium", "approval": "maker_checker", "evidence_required": true, "env_override": "T10_SA_MODE_OPTIONAL_AS_PLANNED", "cache_s": 30, "enforced": true},
