{"key": "cis.quality_modes.t10_adjudicate", "app": "cis", "area": "quality_modes", "label": "T10 tier-2 adjudicator: mode of every class", "description": "off: no call. shadow: the judge's verdicts are recorded only. repair: a violation gets one sentence repair, never a hold (paid judge calls once on). The env var stays an emergency override for one release (a badge on this page). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "value_type": "enum", "unit": null, "min_value": null, "max_value": null, "allowed_values": ["off", "shadow", "repair"], "default_value": "off", "scope_kind": "platform", "impact": "high", "approval": "maker_checker", "evidence_required": true, "env_override": "T10_ADJ_MODE", "cache_s": 30, "enforced": true},
